var t=`1277-accra-fish-fritters`;var r=`world-1277`;var a=`LC`;var n=`central-america-caribbean`;var o=8;var s=1485;var l={en:`Accra Fish Fritters`,ua:`Рибні оладки акра`};var c={en:`Accra Fish Fritters is a dish from Saint Lucia featuring salt cod, all-purpose flour, chicken egg, green onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рибні оладки акра, страва кухні країни Сент-Люсія з такими основними складниками: солона тріска, пшеничне борошно універсальне, куряче яйце, зелена цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Soak salt cod in cold water in the refrigerator for about 24 hours, changing the water several times. Drain before simmering; never soak salted fish at room temperature.`,ua:`Вимочуйте солону тріску в холодній воді в холодильнику близько доби, кілька разів змінюючи воду. Злийте перед варінням; не вимочуйте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,440,`g`],[`water`,1100,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:13,i:[]},{en:`Flake the thoroughly cooked, desalted cod with a fork; remove every bone and keep the fish ready for the mixture.`,ua:`Розберіть повністю приготовану вимочену тріску виделкою на дрібні шматочки, видаліть усі кістки й залиште рибу для суміші.`,t:[`shredding`,`mixing`],m:6,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:11,i:[[`all-purpose-flour`,330,`g`],[`chicken-egg`,2,`pcs`],[`green-onion`,55,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`water`,180,`ml`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,850,`ml`]]}];var h={slug:t,id:r,country:`LC`,region:n,servings:8,minutes:s,title:l,text:c,steps:d};export{a as country,h as default,r as id,s as minutes,n as region,o as servings,t as slug,d as steps,c as text,l as title};